const H = (st, px) => Math.round(px * st.hscale);
const tint = (pct, v = "primary") => `color-mix(in oklab,var(--${v}) ${pct}%,var(--surface))`;
const ink = (k, pct = 78) => `color-mix(in oklab,var(--${k}) ${pct}%,var(--text))`;
const track = "color-mix(in oklab,var(--muted) 15%,var(--surface))";
const av = (ini, s = 28, k = 0) => `<span style="flex:none;width:${s}px;height:${s}px;border-radius:50%;display:grid;place-items:center;font:600 ${Math.round(s * 0.38)}px var(--font-b);background:${tint(16 + (k % 3) * 7, k % 2 ? "accent" : "primary")};color:${ink(k % 2 ? "accent" : "primary", 72)}">${ini}</span>`;
const chip = (t, on) => `<span style="flex:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border-radius:999px;font-size:12.5px;font-weight:500;white-space:nowrap;${on ? "background:var(--primary);color:var(--on-primary);border:1px solid var(--primary)" : "border:1px solid var(--border);background:var(--surface)"}">${t}</span>`;
const seg = (items, on, h = 32) => `<div style="flex:none;display:inline-flex;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)">${items.map((t, i) => `<span style="height:${h}px;padding:0 12px;display:grid;place-items:center;font-size:12.5px;font-weight:500;white-space:nowrap;${i ? "border-left:1px solid var(--border);" : ""}${i === on ? "background:var(--primary);color:var(--on-primary)" : ""}">${t}</span>`).join("")}</div>`;
const sb = (t, k) => `<span style="display:inline-flex;align-items:center;gap:4px;height:20px;padding:0 8px;border-radius:999px;font:600 11px var(--font-b);white-space:nowrap;background:color-mix(in oklab,var(--${k}) 14%,var(--surface));color:${ink(k)}">${t}</span>`;
const cb = (on) => `<span style="flex:none;display:inline-grid;place-items:center;width:16px;height:16px;border-radius:4px;${on ? "background:var(--primary);color:var(--on-primary);border:1px solid var(--primary)" : "border:1.5px solid var(--border)"}">${on ? ic("check", 12) : ""}</span>`;
const stepper = (v, warn, h = 32) => `<span style="flex:none;display:inline-flex;align-items:center;border:1px solid ${warn ? "var(--warning)" : "var(--border)"};border-radius:var(--radius);height:${h}px;background:var(--surface)"><span style="width:28px;display:grid;place-items:center;color:var(--muted)">${ic("minus", 13)}</span><b class="num" style="min-width:26px;text-align:center;font-size:13px">${v}</b><span style="width:28px;display:grid;place-items:center;color:var(--muted)">${ic("plus", 13)}</span></span>`;
const bar = (pct, k = "primary", h = 6) => `<div style="height:${h}px;border-radius:${h}px;background:${track};overflow:hidden"><div style="height:100%;width:${Math.max(2, Math.min(100, pct)).toFixed(1)}%;border-radius:${h}px;background:var(--${k})"></div></div>`;
const ring = (pct, s, w, inner, k = "primary") => { const r = (s - w) / 2, c = 2 * Math.PI * r; return `<div style="position:relative;width:${s}px;height:${s}px;flex:none"><svg width="${s}" height="${s}" style="transform:rotate(-90deg);display:block"><circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="${track}" stroke-width="${w}"/><circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="var(--${k})" stroke-width="${w}" stroke-linecap="round" stroke-dasharray="${(c * pct).toFixed(1)} ${c.toFixed(1)}"/></svg><div style="position:absolute;inset:0;display:grid;place-items:center;align-content:center;text-align:center">${inner}</div></div>`; };
const flame = (s = 18, k = "accent") => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" aria-hidden="true" style="flex:none;display:block"><path d="M12 2.5c.9 3.4 5.6 5.7 5.6 10.9A5.6 5.6 0 0 1 6.4 13.4c0-2.3 1.1-3.9 2.3-5 .1 1.8 1 2.9 2.2 3.4-.2-3.2.2-6.3 1.1-9.3z" fill="var(--${k})"/><path d="M12 12.2c.4 1.5 2.4 2.5 2.4 4.6a2.4 2.4 0 0 1-4.8 0c0-1.3.8-2.2 1.5-2.8.1.6.4 1 .7 1.2-.1-1 .1-2 .2-3z" fill="color-mix(in oklab,var(--${k}) 35%,var(--surface))"/></svg>`;
