const rankRow = ([n, ini, xp, me], i, compact) => { const zone = i < 5 ? "up" : i >= 12 ? "down" : ""; return `<div style="display:flex;align-items:center;gap:${compact ? 10 : 14}px;padding:${compact ? "4px 10px" : "6px 16px"};border-radius:var(--radius);${me ? `background:${tint(14)};outline:1.5px solid var(--primary)` : ""}"><span class="num" style="width:${compact ? 20 : 26}px;text-align:center;font-size:${compact ? 13 : 14}px;color:${i < 3 ? ink("warning", 90) : zone === "up" ? ink("success", 85) : zone === "down" ? ink("danger", 85) : "var(--muted)"}">${i + 1}</span>${av(ini, compact ? 28 : 30, i)}<b style="flex:1;font-weight:${me ? 700 : 500};font-size:${compact ? 13.5 : 14}px">${me ? n + " (you)" : n}</b><span class="num" style="font-size:${compact ? 13 : 14}px">${xp.toLocaleString("en-US")} XP</span></div>`; };
const zoneLine = (t, k) => `<div style="display:flex;align-items:center;gap:10px;font:700 11px var(--font-b);text-transform:uppercase;letter-spacing:.06em;color:${ink(k, 85)};padding:3px 6px">${ic(k === "success" ? "arrow" : "arrow", 13).replace("<svg", `<svg style="transform:rotate(${k === "success" ? -90 : 90}deg)"`)}<span>${t}</span><span style="flex:1;height:1.5px;background:color-mix(in oklab,var(--${k}) 50%,transparent)"></span></div>`;
